// Validate + enrich incoming lead.
// Expected body: { email, phone, full_name, company?, timezone?, ... }
const body = JSON.parse(JSON.stringify(($input.item.json.body || $input.item.json)));

const email = String(body.email || '').trim().toLowerCase();
const phone = String(body.phone || '').trim();
const full_name = String(body.full_name || body.name || '').trim();

const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const phoneValid = /^\+?[1-9]\d{6,14}$/.test(phone.replace(/[\s()-]/g, ''));

if (!emailValid) throw new Error('INVALID_LEAD: bad email');
if (!phoneValid) throw new Error('INVALID_LEAD: bad phone');

// Naive enrichment: derive company from email domain (skip free providers).
const FREE = new Set(['gmail.com','yahoo.com','hotmail.com','outlook.com','icloud.com','proton.me','aol.com']);
const domain = email.split('@')[1];
const derived_company = (!FREE.has(domain) && domain.split('.')[0]) || null;
const company = body.company || (derived_company ? derived_company.charAt(0).toUpperCase() + derived_company.slice(1) : 'Unknown');

// Timezone: trust the form if provided; else fallback to business TZ.
const lead_timezone = body.timezone || $env.BUSINESS_TIMEZONE || 'America/New_York';

return [{ json: {
  email,
  phone: phone.replace(/[\s()-]/g, ''),
  full_name,
  company,
  lead_timezone,
  raw_payload: body,
  received_at: new Date().toISOString()
}}];

// Working-hours compliance check (timezone-aware).
// Returns: { in_hours: bool, scheduled_at: <ISO if not in hours, else null> }
const lead = JSON.parse(JSON.stringify($('Validate + Enrich').item.json));
const tz = lead.lead_timezone || $env.BUSINESS_TIMEZONE || 'America/New_York';
const hStart = parseInt($env.WORKING_HOURS_START || '9', 10);
const hEnd   = parseInt($env.WORKING_HOURS_END   || '18', 10);

const nowParts = new Intl.DateTimeFormat('en-CA', { timeZone: tz, hour: 'numeric', hour12: false, weekday: 'short' }).formatToParts(new Date());
const hourLocal = parseInt(nowParts.find(p => p.type === 'hour').value, 10);
const weekday = nowParts.find(p => p.type === 'weekday').value; // Mon, Tue, ...
const isWeekend = weekday === 'Sat' || weekday === 'Sun';

const in_hours = !isWeekend && hourLocal >= hStart && hourLocal < hEnd;

let scheduled_at = null;
if (!in_hours) {
  // Schedule for next working-hour start in lead's TZ.
  // Simplification: add hours in UTC until the local hour is hStart on a weekday.
  const d = new Date();
  for (let i = 0; i < 72; i++) {
    d.setHours(d.getHours() + 1);
    const p = new Intl.DateTimeFormat('en-CA', { timeZone: tz, hour: 'numeric', hour12: false, weekday: 'short' }).formatToParts(d);
    const h = parseInt(p.find(x => x.type === 'hour').value, 10);
    const w = p.find(x => x.type === 'weekday').value;
    if (h === hStart && w !== 'Sat' && w !== 'Sun') { scheduled_at = d.toISOString(); break; }
  }
  if (!scheduled_at) { d.setHours(d.getHours() + 24); scheduled_at = d.toISOString(); }
}

return [{ json: { ...lead, in_hours, scheduled_at, hour_local: hourLocal, weekday } }];

