// Parse Retell post-call payload.
// Retell posts: { call_id, transcript, transcript_object, metadata, duration_ms,
//                 disconnection_reason, call_cost, recording_url, ... }
const raw = JSON.parse(JSON.stringify($('Webhook: Retell Post-Call').item.json));
const body = raw.body || raw;
const call = body.call || body;

const lead_email = call.metadata && call.metadata.lead_email;
const transcript = call.transcript || (call.transcript_object && call.transcript_object.map(t => `${t.role}: ${t.content}`).join('\n')) || '';
const duration_min = ((call.duration_ms || 0) / 60000).toFixed(2);
const disconnection_reason = call.disconnection_reason || 'unknown';
const retell_cost = (call.call_cost && call.call_cost.combined_cost) || 0;

return [{ json: {
  call_id: call.call_id,
  lead_email,
  transcript,
  duration_min,
  disconnection_reason,
  retell_cost,
  recording_url: call.recording_url || null,
  metadata: call.metadata || {},
  raw_call: call
}}];

