// Normalize LLM output + whitelist-validate. Defaults to safe values on parse error.
const parsed_call = JSON.parse(JSON.stringify($('Parse Retell Payload').item.json));
const raw = JSON.parse(JSON.stringify($input.item.json));
const provider = $env.LLM_PROVIDER || 'openai';

const ALLOWED_INTENTS = ['hot','warm','cold','disqualified'];
const ALLOWED_ACTIONS = ['schedule_meeting','nurture','disqualify'];

let content = '', parsed = null, parse_error = null;
let input_tokens = 0, output_tokens = 0;
try {
  if (provider === 'openai') {
    content = raw.choices && raw.choices[0] && raw.choices[0].message ? raw.choices[0].message.content : '';
    input_tokens  = raw.usage && raw.usage.prompt_tokens || 0;
    output_tokens = raw.usage && raw.usage.completion_tokens || 0;
  } else if (provider === 'anthropic') {
    content = raw.content && raw.content[0] && raw.content[0].text ? raw.content[0].text : '';
    input_tokens  = raw.usage && raw.usage.input_tokens || 0;
    output_tokens = raw.usage && raw.usage.output_tokens || 0;
  }
  const m = content.match(/\{[\s\S]*\}/);
  if (m) parsed = JSON.parse(m[0]);
} catch (e) { parse_error = e.message; }

// Safe defaults — never auto-schedule on parse error.
const SAFE = { bant: { budget: {value: '', score: 0}, authority: {value: '', score: 0}, need: {value: '', score: 0}, timeline: {value: '', score: 0} }, score: 0, intent: 'warm', objections: [], summary: 'Auto-fallback: LLM parse error', next_action: 'nurture' };
const result = parsed || SAFE;
result.intent      = ALLOWED_INTENTS.includes(result.intent)      ? result.intent      : 'warm';
result.next_action = ALLOWED_ACTIONS.includes(result.next_action) ? result.next_action : 'nurture';

// Reconcile intent ↔ next_action.
if (result.intent === 'hot' && result.next_action !== 'schedule_meeting') result.next_action = 'schedule_meeting';
if (result.intent === 'cold' || result.intent === 'disqualified') result.next_action = 'disqualify';

// Compute LLM cost (very rough — adjust for real prices).
const PRICES = { 'openai': { in: 0.00015 / 1000, out: 0.0006 / 1000 }, 'anthropic': { in: 0.003 / 1000, out: 0.015 / 1000 } };
const px = PRICES[provider] || PRICES.openai;
const llm_cost = (input_tokens * px.in) + (output_tokens * px.out);

return [{ json: { ...parsed_call, llm_provider: provider, llm_input_tokens: input_tokens, llm_output_tokens: output_tokens, llm_cost: Number(llm_cost.toFixed(5)), bant_result: result, parse_error } }];

